"""El Guardián - detector de alucinaciones (autocontenido: stdlib + numpy).

Generado por entrenar.py. Ensamble 50/50 de regresión logística y ExtraTrees,
exportados como arrays NumPy (no requiere scikit-learn). El score se reescala
para que el corte de decisión óptimo (_U_FINAL) quede en 0.5.
"""
import base64
import pickle
import zlib

import numpy as np

import re
import math
import unicodedata

_NUM_WORDS = {"dos": 2, "tres": 3, "cuatro": 4, "cinco": 5, "seis": 6, "siete": 7,
              "ocho": 8, "nueve": 9, "diez": 10, "once": 11, "doce": 12,
              "trece": 13, "catorce": 14, "quince": 15, "veinte": 20,
              "treinta": 30, "cuarenta": 40, "cincuenta": 50, "cien": 100,
              "ciento": 100}
_STOP = {"para", "como", "pero", "desde", "hasta", "sobre", "entre", "esta",
         "este", "esos", "unos", "unas", "tiene", "tuvo", "cada", "donde",
         "cuando", "tambien", "estos", "estas", "sido", "fueron", "tenia"}

_CAUS = [" gracias a ", " debido ", " porque ", " por eso ", " causa", " motivo",
         " provoc", " consecuencia", " llevo a ", " para evitar", " con el fin",
         " razon", " ya que ", " lo que ", " lo cual ", " por lo que ",
         " permitio", " permitiendo", " como resultado", " por ello", " dado que "]
_GEN = [" todos ", " todas ", " siempre ", " nunca ", " ningun", " cualquier",
        " toda ", " todo ", " la totalidad", " en general", " generalmente",
        " habitualmente", " del pais", " en todo ", " cada "]
_STRONG = [" aprobo", " inmuniz", " garantiz", " confirm", " demostr", " logro",
           " elimin", " asegur", " prohib", " obligo", " obligator", " reconoci",
           " certific", " finaliz", " resolvi", " concedi", " ejecut"]
_HEDGE = [" podria", " podrian", " solo ", " unicamente", " alrededor",
          " aproximadamente", " aprox", " mas de ", " menos de ", " hasta ",
          " al menos", " cerca de", " casi ", " estima", " previst", " propuso",
          " propuest", " podra", " preve", " posible", " algunos ", " algunas ",
          " varios ", " parte de ", " en torno"]
_ANT = [(" aument", " dismin"), (" aument", " cay"), (" subi", " baj"),
        (" crec", " reduc"), (" abri", " cerr"), (" gano", " perd"),
        (" increment", " reduc"), (" increment", " recort"),
        (" aprob", " rechaz"), (" mayor", " menor"), (" antes", " despues")]


def _norm(t):
    t = unicodedata.normalize("NFD", str(t if t is not None else "").lower())
    return "".join(c for c in t if unicodedata.category(c) != "Mn")


def _pad(t):
    return " " + re.sub(r"\s+", " ", re.sub(r"[^a-z0-9% ]", " ", _norm(t))) + " "


def _num(v, d=0.0):
    try:
        x = float(v)
        return d if x != x else x
    except Exception:
        return d


def _g(d, *keys, default=None):
    if isinstance(d, dict):
        for k in keys:
            if k in d and d[k] is not None:
                return d[k]
    return default


def _flat(v):
    out = []
    if isinstance(v, (list, tuple)):
        for e in v:
            out.extend(_flat(e))
    elif isinstance(v, dict):
        for e in v.values():
            out.extend(_flat(e))
    else:
        try:
            out.append(float(v))
        except Exception:
            pass
    return out


def _parse_nums(texto):
    t = _norm(texto)
    out = []
    for m in re.finditer(r"\d+(?:[.,]\d+)*", t):
        s = m.group(0)
        if re.fullmatch(r"\d{1,3}(?:\.\d{3})+", s):
            s = s.replace(".", "")
        else:
            s = s.replace(",", ".")
        try:
            out.append(float(s))
        except ValueError:
            pass
    for w in re.findall(r"[a-z]+", t):
        if w in _NUM_WORDS:
            out.append(float(_NUM_WORDS[w]))
    return out


def _rs(nums):
    return set(round(x, 4) for x in nums)


def _derive(nums):
    base = sorted(nums)[:45]
    d = set()
    for a in base:
        d.update((round(a * 2, 4), round(a / 2.0, 4),
                  round(a * 1000, 4), round(a / 1000.0, 4)))
        for b in base:
            d.add(round(a + b, 4))
            d.add(round(abs(a - b), 4))
            d.add(round(a * b / 100.0, 4))
            if b:
                d.add(round(a / b * 100.0, 4))
                d.add(round(a / b, 4))
    return d


def _toks(t):
    return set(w[:5] for w in re.findall(r"[a-z]{4,}", _norm(t)) if w not in _STOP)


def _src_texts(caso):
    fu = caso.get("fuentes") or []
    if isinstance(fu, str):
        fu = [fu]
    out = []
    for s in fu:
        if isinstance(s, dict):
            s = _g(s, "texto", "text", default="")
        out.append(str(s))
    return out


def _clauses(resp):
    out = []
    for s in re.split(r"(?<=[.!?])\s+", str(resp or "").strip()):
        for c in re.split(r",\s|;|:\s|\sy\s|\se\s|\spero\s|\smientras\s|\saunque\s", s):
            if c.strip():
                out.append(c.strip())
    return out


# ---- señales de los modelos ------------------------------------------------
def _units(sen, kind):
    if kind == "oraciones":
        if isinstance(sen, list):
            return [u for u in sen if isinstance(u, dict)]
        if isinstance(sen, dict):
            for n in ("oraciones", "frases"):
                if isinstance(sen.get(n), list):
                    return [u for u in sen[n] if isinstance(u, dict)]
        return []
    if isinstance(sen, dict) and isinstance(sen.get("fragmentos"), list):
        return [u for u in sen["fragmentos"] if isinstance(u, dict)]
    out = []
    for u in _units(sen, "oraciones"):
        fr = u.get("fragmentos")
        if isinstance(fr, list):
            out.extend(x for x in fr if isinstance(x, dict))
    return out


def _unit_stats(u):
    rs = _flat(_g(u, "respaldo_por_fuente", default=[]))
    cs = _flat(_g(u, "contradiccion_por_fuente", default=[]))
    ss = _flat(_g(u, "similitud_por_fuente", default=[]))
    sup = max(rs) if rs else 0.0
    con = max(cs) if cs else 0.0
    sim = max(ss) if ss else 0.0
    ra = _num(_g(u, "respaldo_todas"), sup)
    ca = _num(_g(u, "contradiccion_todas"), con)
    llm = _g(u, "llm", default={})
    if not isinstance(llm, dict):
        llm = {"veredicto": llm}
    ver = _norm(_g(llm, "veredicto", "verdict", default=""))
    conf = min(1.0, max(0.0, _num(_g(llm, "confianza", "confidence"), 0.5)))
    uns = ("no_resp" in ver) or ("no resp" in ver)
    cnt = "contrad" in ver
    ok = ("resp" in ver) and not uns
    pl = conf if (uns or cnt) else ((1.0 - conf) if ok else 0.5)
    return dict(sup=sup, con=con, sim=sim, ra=ra, ca=ca, pl=pl, uns=float(uns),
                cnt=float(cnt), ok=ok, conf=conf)


def _agg(units, p, f):
    rows = [_unit_stats(u) for u in units]
    n = len(rows)
    f[p + "n"] = float(n)
    keys = ["sup_min", "sup_mean", "all_min", "all_mean", "con_max", "conall_max",
            "sim_min", "llm_max", "llm_mean", "llm_uns", "llm_con", "llm_bad_frac",
            "dis_max", "dis_cnt", "rev_max", "lowc"]
    if n == 0:
        for k in keys:
            f[p + k] = 0.0
        for k in ("sup_min", "sup_mean", "all_min", "all_mean", "sim_min", "llm_max", "llm_mean"):
            f[p + k] = 0.5
        return
    best = [max(r["sup"], r["ra"]) for r in rows]
    f[p + "sup_min"] = min(r["sup"] for r in rows)
    f[p + "sup_mean"] = sum(r["sup"] for r in rows) / n
    f[p + "all_min"] = min(r["ra"] for r in rows)
    f[p + "all_mean"] = sum(r["ra"] for r in rows) / n
    f[p + "con_max"] = max(r["con"] for r in rows)
    f[p + "conall_max"] = max(r["ca"] for r in rows)
    f[p + "sim_min"] = min(r["sim"] for r in rows)
    f[p + "llm_max"] = max(r["pl"] for r in rows)
    f[p + "llm_mean"] = sum(r["pl"] for r in rows) / n
    f[p + "llm_uns"] = sum(r["uns"] for r in rows)
    f[p + "llm_con"] = sum(r["cnt"] for r in rows)
    f[p + "llm_bad_frac"] = (f[p + "llm_uns"] + f[p + "llm_con"]) / n
    # El juez dice "respaldada" pero el NLI no encuentra respaldo (y al revés)
    f[p + "dis_max"] = max((1.0 - r["pl"]) * (1.0 - b) for r, b in zip(rows, best))
    f[p + "dis_cnt"] = float(sum(1 for r, b in zip(rows, best) if r["ok"] and b < 0.3))
    f[p + "rev_max"] = max(r["pl"] * b for r, b in zip(rows, best))
    f[p + "lowc"] = float(sum(1 for r in rows if r["ok"] and r["conf"] < 0.75))


# ---- características del texto frente a las fuentes ------------------------
def _text_feats(caso, f):
    srcs = _src_texts(caso)
    nsrc = [_pad(s) for s in srcs]
    stoks = [_toks(s) for s in srcs]
    snums = [_rs(_parse_nums(s)) for s in srcs]
    allnums = set()
    for s in snums:
        allnums |= s
    union = set()
    for s in stoks:
        union |= s
    derived = _derive(allnums)

    a = dict(cl=0, bmin=1.0, bsum=0.0, nov_max=0.0, nov_cnt=0, n_nums=0,
             n_unsup=0, n_mis=0, caus_b=0, caus_g=0, gen_b=0, gen_g=0,
             str_b=0, str_g=0, hdrop=0, negd=0, ant=0)
    for c in _clauses(caso.get("respuesta")):
        ct = _toks(c)
        cn = _parse_nums(c)
        if not ct and not cn:
            continue
        nc = _pad(c)
        b, bc = -1, 0.0
        if ct:
            for i, st in enumerate(stoks):
                v = len(ct & st) / len(ct)
                if v > bc:
                    b, bc = i, v
            nov = ct - union
            a["nov_cnt"] += len(nov)
            a["nov_max"] = max(a["nov_max"], len(nov) / len(ct))
            a["bmin"] = min(a["bmin"], bc)
            a["bsum"] += bc
        a["cl"] += 1
        nb = nsrc[b] if b >= 0 else " "

        for x in cn:
            k = round(x, 4)
            a["n_nums"] += 1
            if b >= 0 and k in snums[b]:
                continue
            if k in derived and k not in allnums:
                continue                      # sale de una cuenta exacta
            if k in allnums:
                a["n_mis"] += 1               # existe, pero en otra fuente
            else:
                a["n_unsup"] += 1             # no está en ningún sitio

        for m in _CAUS:
            if m in nc and m not in nb:
                a["caus_b"] += 1
                a["caus_g"] += not any(m in s for s in nsrc)
        for m in _GEN:
            if m in nc and m not in nb:
                a["gen_b"] += 1
                a["gen_g"] += not any(m in s for s in nsrc)
        for m in _STRONG:
            if m in nc and m not in nb:
                a["str_b"] += 1
                a["str_g"] += not any(m in s for s in nsrc)
        if bc >= 0.5:
            for m in _HEDGE:
                if m in nb and m not in nc:
                    a["hdrop"] += 1
            neg = r"\b(?:no|sin|nunca|ni|tampoco)\b"
            if bool(re.search(neg, nc)) != bool(re.search(neg, nb)):
                a["negd"] += 1
        if bc >= 0.4:
            for x, y in _ANT:
                if (x in nc and y in nb and x not in nb) or (y in nc and x in nb and y not in nb):
                    a["ant"] += 1

    ncl = max(a["cl"], 1)
    f["tx_clauses"] = float(a["cl"])
    f["tx_best_min"] = a["bmin"]
    f["tx_best_mean"] = a["bsum"] / ncl
    f["tx_novel_max"] = a["nov_max"]
    f["tx_novel_cnt"] = float(a["nov_cnt"])
    f["tx_nums"] = float(a["n_nums"])
    f["tx_num_unsup"] = float(a["n_unsup"])
    f["tx_num_mis"] = float(a["n_mis"])
    f["tx_num_bad_frac"] = (a["n_unsup"] + a["n_mis"]) / max(a["n_nums"], 1)
    for k in ("caus_b", "caus_g", "gen_b", "gen_g", "str_b", "str_g", "hdrop", "negd", "ant"):
        f["tx_" + k] = float(a[k])
    f["tx_nsrc"] = float(len(srcs))


def _extract_feats(caso):
    f = {}
    sen = caso.get("senales")
    _agg(_units(sen, "oraciones"), "s_", f)
    _agg(_units(sen, "fragmentos"), "g_", f)
    _text_feats(caso, f)
    return [float(f[k]) for k in sorted(f)]

